require "rails_helper"

RSpec.describe Timekeeping::ProjectionConsumer, "stale generation refusal records" do
  it "records a stale_generation refusal under each company in the refused batch and under no other company" do
    company_a = create(:company)
    company_b = create(:company)
    bystander = create(:company)
    project_a = create(:project, client: create(:client, company: company_a))
    project_b = create(:project, client: create(:client, company: company_b))
    TimekeepingOwnership.current.update!(generation: 3, handoff_step: nil)

    batch = TimekeepingSnapshots.batch(
      TimekeepingSnapshots.item(
        TimekeepingSnapshots.entry(id: 93_001, company_id: company_a.id, version: 1, project_id: project_a.id,
                                   user_id: create(:user).id),
        generation: 2, outbox_position: 1
      ),
      TimekeepingSnapshots.item(
        TimekeepingSnapshots.entry(id: 93_002, company_id: company_b.id, version: 1, project_id: project_b.id,
                                   user_id: create(:user).id),
        generation: 2, outbox_position: 2
      )
    )

    result = described_class.call(batch:, idempotency_key: SecureRandom.uuid)

    # "any `409 stale_generation` outside a handoff;" is alerted per company, so
    # each refused company gets its own row and a bystander gets none.
    expect(result.status).to eq(409)
    expect(TimekeepingStaleGenerationRefusal.order(:company_id).pluck(:company_id, :handoff_step))
      .to eq([[company_a.id, nil], [company_b.id, nil]].sort)
    expect(TimekeepingStaleGenerationRefusal.where(company_id: bystander.id)).to be_empty
  end
end

